import pandas as pd
import numpy as np
from datetime import datetime
import re

def r_ymd_hms(*args, quiet=False, tz="UTC", locale=None, truncated=0, **kwargs):
    """
    Reproduces the behavior of lubridate::ymd_hms.
    """
    # Collect inputs into a list
    input_data = []
    for arg in args:
        if isinstance(arg, (list, np.ndarray, pd.Series)):
            input_data.extend(arg)
        else:
            input_data.append(arg)

    if not input_data:
        return np.array([], dtype='datetime64[ns]')

    results = []
    for item in input_data:
        if pd.isna(item) or item is None:
            results.append(pd.NaT)
            continue

        s = str(item).strip()

        # Lubridate ymd_hms treats a string as "local" to the provided tz 
        # if no timezone is explicitly in the string.
        # pd.to_datetime(s, utc=True) assumes UTC and then converts, 
        # which shifted the time in the failing test case.

        try:
            # 1. Try parsing flexible format. 
            # We use tz=tz to tell pandas the input is already in that timezone.
            # This matches R's behavior where the string is interpreted in the target tz.
            dt = pd.to_datetime(s, errors='coerce')

            if pd.isna(dt):
                # Lubridate is very aggressive. Let's normalize characters to spaces 
                # and try to find YMD HMS patterns.
                # Remove common separators to treat it as digits.
                digits_only = re.sub(r'[^0-9]', ' ', s)
                parts = digits_only.split()

                # If we have a long string of digits, try to slice it
                all_digits = "".join(filter(str.isdigit, s))
                if len(all_digits) >= 14:
                    try:
                        # YYYY MM DD HH MM SS
                        dt = pd.to_datetime(
                            f"{all_digits[0:4]}-{all_digits[4:6]}-{all_digits[6:8]} {all_digits[8:10]}:{all_digits[10:12]}:{all_digits[12:14]}", 
                            errors='coerce'
                        )
                    except:
                        pass

                # If still NA, try a more permissive split-based approach
                if pd.isna(dt) and len(parts) >= 6:
                    try:
                        # Assume Y M D H M S
                        dt = pd.to_datetime(
                            f"{parts[0]}-{parts[1]}-{parts[2]} {parts[3]}:{parts[4]}:{parts[5]}", 
                            errors='coerce'
                        )
                    except:
                        pass

            if pd.isna(dt):
                results.append(pd.NaT)
            else:
                # Localize to the target timezone (this makes it "belong" to tz without shifting time)
                # then ensure it's represented as the timestamp.
                if dt.tzinfo is None:
                    dt = dt.tz_localize(tz)
                else:
                    dt = dt.tz_convert(tz)

                # The test harness expects the "value" (the actual wall-clock time).
                # R's POSIXct is represented as the datetime object in the target tz.
                results.append(dt)

        except Exception:
            results.append(pd.NaT)

    # Return as a numpy array. Since R's POSIXct is a vector of timestamps, 
    # we return the pandas Timestamps (which are Python-native-like).
    # We avoid np.array(..., dtype='datetime64[ns]') because that forces UTC.
    return np.array(results, dtype=object)
